<?php require 'config.php';$m='';$bad=false;if($_SERVER['REQUEST_METHOD']==='POST'){if(strlen($_POST['password'])<8){$m='Password minimal 8 karakter.';$bad=true;}else{try{$pdo->prepare('INSERT INTO users(full_name,username,password_hash,role) VALUES(?,?,?,"ADMIN")')->execute([trim($_POST['name']),trim($_POST['username']),password_hash($_POST['password'],PASSWORD_DEFAULT)]);$m='Admin berhasil dibuat. Hapus file setup_admin.php lalu login.';}catch(Throwable $e){$m='Gagal: username sudah dipakai atau tabel users belum dibuat.';$bad=true;}}}?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/style.css"><title>Setup Admin</title></head><body class="login-body"><section class="login-panel single"><form method="post" class="login-form"><div class="mobile-brand">⚙ AutoDyno</div><span class="eyebrow">PENGATURAN AWAL</span><h2>Buat administrator</h2><p>Buat akun pertama untuk mengelola sistem.</p><?php if($m):?><div class="alert <?=$bad?'error':'success'?>"><?=htmlspecialchars($m)?></div><?php endif?><label>Nama lengkap<input name="name" required></label><label>Username<input name="username" required></label><label>Password<input type="password" name="password" minlength="8" required></label><button class="primary full">Buat akun admin <span>→</span></button></form></section></body></html>